const config = $('Config Cliente').first().json;
const items = $input.all();
const base = String(config.site_imobiliaria || '').replace(/\/$/, '');
const limite = Number(config.limite_opcoes_site || 6);
const filtros = items.find(i => i.json.filtros)?.json.filtros || $('Preparar URLs - Busca Inteligente').first().json.filtros || {};

function absolutize(link) {
  if (!link) return '';
  link = String(link).trim().replace(/&amp;/g, '&');
  if (link.startsWith('http')) return link;
  if (link.startsWith('//')) return 'https:' + link;
  if (link.startsWith('/')) return base + link;
  return base + '/' + link.replace(/^\/+/, '');
}

function stripTags(s) {
  return String(s || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function slugMatch(text, terms) {
  const t = String(text || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  return terms.some(term => term && t.includes(String(term).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()));
}

const urls = new Map();
const propertyTerms = ['imovel','imoveis','casa','apartamento','terreno','sobrado','alugar','locacao','locação','comprar','venda','empreendimento'];

for (const item of items) {
  const content = item.json.body || item.json.data || item.json.response || JSON.stringify(item.json || {});
  const html = String(content || '');
  if (!html || html.length < 20) continue;

  // sitemap.xml: <loc>https://...</loc>
  for (const m of html.matchAll(/<loc>\s*([^<]+)\s*<\/loc>/gi)) {
    const url = absolutize(m[1]);
    if (slugMatch(url, propertyTerms)) urls.set(url, { url, fonte: 'sitemap', titulo: '', descricao: '' });
  }

  // HTML anchors with local context
  const anchorRegex = /<a\b([^>]*?)href=["']([^"']+)["']([^>]*)>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = anchorRegex.exec(html)) !== null) {
    const href = m[2];
    const url = absolutize(href);
    const anchorText = stripTags(m[4]);
    const start = Math.max(0, m.index - 800);
    const end = Math.min(html.length, anchorRegex.lastIndex + 1200);
    const contexto = stripTags(html.slice(start, end));
    const combined = `${url} ${anchorText} ${contexto}`;

    if (!slugMatch(combined, propertyTerms)) continue;

    const preco = (contexto.match(/R\$\s?[0-9\.]+(?:,[0-9]{2})?/i) || [''])[0];
    const bairro = (contexto.match(/(?:bairro|setor|jardim|vila|centro)[:\s-]+([A-Za-zÀ-ÿ0-9\s]{2,40})/i) || [,''])[1]?.trim() || '';

    if (!urls.has(url)) {
      urls.set(url, {
        url,
        fonte: item.json.fonte || 'html',
        titulo: anchorText.slice(0, 140),
        preco,
        bairro,
        descricao: contexto.slice(0, 900)
      });
    }
  }
}

let imoveis = [...urls.values()];

// Filtro leve antes da IA, sem matar resultado quando site é pobre
const tipo = filtros.tipo && filtros.tipo !== 'indefinido' ? filtros.tipo : '';
const finalidade = filtros.finalidade && filtros.finalidade !== 'indefinido' ? filtros.finalidade : '';
const cidade = filtros.cidade || config.cidade || '';
const palavras = [...(filtros.palavras_chave || []), filtros.bairro || '', filtros.quartos ? `${filtros.quartos}` : ''].filter(Boolean);

imoveis = imoveis.map((im, idx) => {
  let score_match = 0;
  const blob = `${im.url} ${im.titulo} ${im.descricao}`;
  if (tipo && slugMatch(blob, [tipo])) score_match += 3;
  if (finalidade && slugMatch(blob, [finalidade, finalidade === 'locacao' ? 'alugar' : 'comprar'])) score_match += 3;
  if (cidade && slugMatch(blob, [cidade])) score_match += 2;
  for (const p of palavras) if (slugMatch(blob, [p])) score_match += 1;
  return { ...im, score_match, opcao: idx + 1 };
}).sort((a,b) => b.score_match - a.score_match).slice(0, Math.max(limite * 3, 12));

return [{
  json: {
    filtros,
    total_imoveis_encontrados: imoveis.length,
    imoveis_encontrados: imoveis,
    lead_id: $('Mesclar ID Lead Supabase').first().json.lead_id || '',
    busca_site_status: imoveis.length ? 'encontrou_opcoes' : 'sem_opcoes'
  }
}];

const config = $('Config Cliente').first().json;
const raw = $json.output?.[0]?.content?.[0]?.text || '{}';
const clean = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

function slug(v) {
  return String(v || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/ç/g, 'c')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

let filtros;
try { filtros = JSON.parse(clean); } catch (e) { filtros = {}; }

filtros.finalidade = filtros.finalidade || 'indefinido';
filtros.tipo = filtros.tipo || 'indefinido';
filtros.cidade = filtros.cidade || config.cidade;
filtros.bairro = filtros.bairro || '';
filtros.quartos = filtros.quartos || '';
filtros.valor_maximo = filtros.valor_maximo || '';
filtros.palavras_chave = Array.isArray(filtros.palavras_chave) ? filtros.palavras_chave : [];

const base = String(config.site_imobiliaria || '').replace(/\/$/, '');
const paths = Array.isArray(config.paths_imobiliarios) ? config.paths_imobiliarios : ['/imovel', '/imoveis', '/venda', '/comprar', '/alugar', '/locacao'];
const urls = [];

function add(url, fonte) {
  if (!url) return;
  const finalUrl = url.startsWith('http') ? url : base + (url.startsWith('/') ? url : '/' + url);
  if (!urls.find(u => u.url === finalUrl)) urls.push({ url: finalUrl, fonte });
}

add(base, 'home');
add(base + (config.sitemap_path || '/sitemap.xml'), 'sitemap');

for (const p of paths) {
  const path = p.startsWith('/') ? p : '/' + p;
  add(path, 'path_base');

  // tenta padrões comuns de sites imobiliários
  const finalidade = filtros.finalidade === 'locacao' ? 'alugar' : (filtros.finalidade === 'venda' || filtros.finalidade === 'compra' ? 'comprar' : filtros.finalidade);
  if (finalidade && finalidade !== 'indefinido') add(`${path}/${finalidade}`, 'path_finalidade');
  if (filtros.tipo && filtros.tipo !== 'indefinido') add(`${path}/${finalidade || ''}/${slug(filtros.tipo)}`, 'path_tipo');
  if (filtros.cidade) add(`${path}/${finalidade || ''}/${slug(filtros.tipo || '')}/${slug(filtros.cidade)}`, 'path_cidade');
}

return urls.slice(0, 18).map(u => ({
  json: {
    ...u,
    filtros,
    site_base: base,
    lead_id: $('Mesclar ID Lead Supabase').first().json.lead_id || ''
  }
}));

