const webhook = $('Webhook').first().json;
const config = $('Config Cliente').first().json;

const telefone = webhook.from || webhook.body?.payload?.from || webhook.payload?.from || webhook.body?.from || '';
const mensagem = webhook.body?.body || webhook.payload?.body || webhook.body || '';
const nome = webhook.pushName || webhook.name || 'não informado';

return [
  {
    json: {
      data: new Date().toISOString(),
      imobiliaria: config.imobiliaria,
      session: config.session,
      nome,
      telefone,
      mensagem,
      cidade_detectada: $('Edit Fields1').first().json.city || '',
      cidade_valida: true,
      intencao: "nao_classificado",
      tipo_negocio: "nao_classificado",
      imovel_especifico: "nao_informado",
      origem: "nao_informado",
      etapa: "recebido",
      lgpd: "nao_solicitado",
      score: 0,
      temperatura: "nao_classificado",
      status: "recebido"
    }
  }
];

function safeNode(name) {
  try { return $(name).first().json || {}; } catch (e) { return {}; }
}
function cleanStr(v){ return String(v || '').trim(); }
function hasRef(v){
  const s = cleanStr(v).toLowerCase();
  return !!s && !['nao_informado','não informado','vazio','undefined','null'].includes(s);
}

const config = safeNode('Config Cliente');
const baseLead = safeNode('Mesclar ID Lead Supabase');
const prepararLead = safeNode('Preparar Lead');
const editFields = safeNode('Edit Fields');
const cidadeAnterior = safeNode('Edit Fields1');
const memoriaNode = safeNode('Normalizar Memória do Lead');
const memoria = memoriaNode.memoria_lead || {};

const raw = $json.output?.[0]?.content?.[0]?.text || '{}';
const clean = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

let etapa = {};
let parse_ok = true;
let parse_error = '';
try { etapa = JSON.parse(clean); } catch(e) { parse_ok = false; parse_error = e.message; etapa = {}; }

const allowed = ['BUSCAR_IMOVEIS','CONSULTAR_BASE','PEDIR_ESCOLHA','LGPD','ANALISE_CREDITO','RESPONDER_DUVIDA','CORRETOR'];
const acaoOriginal = etapa.proxima_acao;
let acao = cleanStr(etapa.proxima_acao).toUpperCase();
let fallback_aplicado = false;
let motivo_fallback = '';

if (!allowed.includes(acao)) {
  acao = 'PEDIR_ESCOLHA';
  fallback_aplicado = true;
  motivo_fallback = 'acao_invalida_ou_vazia';
}

let confianca = Number(etapa.confianca);
if (!Number.isFinite(confianca)) confianca = 0.5;
confianca = Math.max(0, Math.min(1, confianca));

const confiancaMinima = Number(config.confianca_minima_acao ?? 0.62);
if (confianca < confiancaMinima && !['CORRETOR','PEDIR_ESCOLHA'].includes(acao)) {
  acao = config.fallback_acao_baixa_confianca || 'RESPONDER_DUVIDA';
  fallback_aplicado = true;
  motivo_fallback = `baixa_confianca_${confianca}`;
}

const risco = cleanStr(etapa.risco_inventar || 'BAIXO').toUpperCase();
if (risco === 'ALTO' && acao === 'RESPONDER_DUVIDA') {
  acao = 'CONSULTAR_BASE';
  fallback_aplicado = true;
  motivo_fallback = 'risco_alto_inventar_consultar_base';
}

const imovelRef = hasRef(etapa.imovel_referencia) ? etapa.imovel_referencia : (hasRef(memoria.imovel_referencia) ? memoria.imovel_referencia : '');
const temImovel = !!etapa.tem_imovel_especifico || !!etapa.imovel_escolhido || !!memoria.imovel_escolhido || hasRef(imovelRef);

// TRAVA V4.0: corretor nunca ajuda a escolher imóvel. Primeiro a IA ajuda o lead a escolher.
if (acao === 'CORRETOR' && !temImovel && (config.regra_corretor_apenas_com_imovel ?? true)) {
  acao = 'BUSCAR_IMOVEIS';
  fallback_aplicado = true;
  motivo_fallback = 'trava_v4_corretor_sem_imovel_escolhido';
}

// Proteção: análise só com imóvel/referência e LGPD/dados.
if (acao === 'ANALISE_CREDITO' && !temImovel) {
  acao = 'PEDIR_ESCOLHA';
  fallback_aplicado = true;
  motivo_fallback = 'analise_sem_imovel_especifico';
}

function toTipoSlug(v) { return String(v || 'INDEFINIDO').toLowerCase().replace(/_/g,'-'); }

const intencao = etapa.intencao || memoria.intencao || 'INDEFINIDO';
const filtros_busca = {
  finalidade: intencao === 'LOCACAO' ? 'locacao' : (intencao === 'COMPRA' ? 'venda' : (intencao === 'INVESTIMENTO' ? 'investimento' : (memoria.finalidade || 'indefinido'))),
  tipo: etapa.tipo_imovel && etapa.tipo_imovel !== 'INDEFINIDO' ? toTipoSlug(etapa.tipo_imovel) : (memoria.tipo_imovel ? toTipoSlug(memoria.tipo_imovel) : 'indefinido'),
  cidade: etapa.cidade && etapa.cidade !== 'NAO_INFORMADO' ? etapa.cidade : (memoria.cidade || config.cidade || ''),
  bairro: etapa.bairro || memoria.bairro || '',
  quartos: etapa.quartos || memoria.quartos || '',
  valor_maximo: etapa.valor_maximo || memoria.valor_maximo || '',
  palavras_chave: [etapa.tipo_imovel || memoria.tipo_imovel, etapa.bairro || memoria.bairro, etapa.quartos ? `${etapa.quartos} quartos` : ''].filter(Boolean)
};

const fallbackText = config.mensagem_fallback_baixa_confianca || 'Consigo te ajudar com imóveis, localização, documentação, visitas ou conectar você com um corretor quando você escolher uma opção. Você procura comprar, alugar ou tirar uma dúvida?';
const interesseVisita = !!etapa.interesse_visita || !!memoria.interesse_visita;
const urgencia = cleanStr(etapa.urgencia || memoria.urgencia || 'NAO_INFORMADO').toUpperCase();
let etapaFunil = etapa.etapa_funil || memoria.etapa_funil || acao;
if (temImovel && acao !== 'BUSCAR_IMOVEIS') etapaFunil = etapaFunil === 'novo' ? 'imovel_escolhido' : etapaFunil;

return [{ json: {
  ...prepararLead,
  ...baseLead,
  memoria_lead: memoria,
  memoria_existe: !!memoriaNode.memoria_existe,
  memoria_id: memoriaNode.memoria_id || '',
  origem: etapa.origem || memoria.origem || prepararLead.origem || 'NAO_INFORMADO',
  nome_cliente_ia: etapa.nome_cliente || memoria.nome || 'NAO_INFORMADO',
  cidade: etapa.cidade || memoria.cidade || cidadeAnterior.city || '',
  intencao,
  tipo_negocio: intencao,
  tipo_imovel: etapa.tipo_imovel || memoria.tipo_imovel || 'INDEFINIDO',
  tem_imovel_especifico: temImovel,
  imovel_escolhido: temImovel,
  imovel_especifico: imovelRef || 'nao_informado',
  imovel_referencia: imovelRef,
  precisa_buscar_imoveis: !!etapa.precisa_buscar_imoveis || acao === 'BUSCAR_IMOVEIS',
  pode_ir_para_lgpd: !!etapa.pode_ir_para_lgpd && temImovel,
  lgpd_aceita: !!etapa.lgpd_aceita,
  dados_financeiros_presentes: !!etapa.dados_financeiros_presentes,
  interesse_visita: interesseVisita,
  urgencia,
  etapa_funil: etapaFunil,
  pergunta_base_conhecimento: etapa.pergunta_base_conhecimento || editFields.message || '',
  categoria_base_sugerida: etapa.categoria_base_sugerida || 'VAZIO',
  resposta_curta_sugerida: etapa.resposta_curta_sugerida || (fallback_aplicado ? fallbackText : ''),
  filtros_busca,
  filtros: filtros_busca,
  etapa: acao,
  proxima_acao: acao,
  acao_original_ia: acaoOriginal || '',
  confianca_ia: confianca,
  motivo_acao: etapa.motivo_acao || '',
  risco_inventar: risco,
  dados_faltantes: Array.isArray(etapa.dados_faltantes) ? etapa.dados_faltantes : [],
  fallback_aplicado,
  motivo_fallback,
  parse_ok,
  parse_error,
  raw_ia_orquestradora: raw,
  classificacao_etapa_raw: etapa
}}];

