const config = $('Config Cliente').first().json;
const etapa = $('Normalizar Etapa do Lead').first().json;
const raw = $json.output?.[0]?.content?.[0]?.text || '{}';
const clean = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

let a;
try { a = JSON.parse(clean); } catch(e) { a = {}; }

function money(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (typeof v === 'number') return v;
  const s = String(v)
    .toLowerCase()
    .replace(/r\$/g, '')
    .replace(/\s/g, '')
    .replace(/mil/g, '000')
    .replace(/\./g, '')
    .replace(',', '.');
  const n = Number(s.replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : 0;
}

function norm(v) {
  return String(v || 'NAO_INFORMADO').trim().toUpperCase();
}

const tipo = norm(a.tipo_negocio || etapa.intencao);
const valorImovel = money(a.valor_imovel);
const valorAluguel = money(a.valor_aluguel);
const renda = money(a.renda_mensal);
const entrada = money(a.entrada);
const fgts = norm(a.fgts);
const restricao = norm(a.restricao);
const comprovante = norm(a.comprovante_renda);
const garantia = norm(a.garantia_locacao);
const urgencia = norm(a.urgencia);

const temImovel = Boolean(etapa.tem_imovel_especifico || etapa.imovel_especifico || etapa.imovel_referencia);
const multLocacao = Number(config.renda_minima_locacao_multiplicador || 3);
const minQuente = Number(config.score_lead_quente || 8);
const minMedio = Number(config.score_lead_medio || 5);

let score = 0;
const motivos = [];
const faltando = [];

// Regra universal: sem imóvel escolhido não vira quente
if (temImovel) { score += 2; motivos.push('imóvel/referência definido'); }
else { faltando.push('imóvel escolhido'); }

if (['COMPRA', 'INVESTIMENTO'].includes(tipo)) {
  if (renda > 0) { score += 2; motivos.push('renda informada'); } else faltando.push('renda familiar');
  if (entrada > 0) { score += 2; motivos.push('entrada informada'); } else faltando.push('entrada disponível');
  if (fgts === 'SIM') { score += 1; motivos.push('possui FGTS'); }
  if (restricao === 'NAO') { score += 2; motivos.push('sem restrição informada'); }
  else if (restricao === 'SIM') { score -= 3; motivos.push('informou restrição no nome'); }
  else faltando.push('situação de restrição');
  if (urgencia === 'ALTA') { score += 1; motivos.push('alta urgência'); }

  // Sinal de compatibilidade simples: entrada >= 10% do valor do imóvel
  if (valorImovel > 0 && entrada > 0) {
    const percEntrada = entrada / valorImovel;
    if (percEntrada >= 0.20) { score += 1; motivos.push('entrada forte'); }
    else if (percEntrada < 0.10) { score -= 1; motivos.push('entrada abaixo de 10%'); }
  }
}

if (tipo === 'LOCACAO') {
  if (renda > 0) { score += 2; motivos.push('renda informada'); } else faltando.push('renda mensal');
  if (valorAluguel > 0) { score += 1; motivos.push('aluguel informado'); } else faltando.push('valor do aluguel');
  if (renda > 0 && valorAluguel > 0) {
    const rendaMinima = valorAluguel * multLocacao;
    if (renda >= rendaMinima) { score += 3; motivos.push(`renda compatível: >= ${multLocacao}x o aluguel`); }
    else { score -= 2; motivos.push(`renda abaixo de ${multLocacao}x o aluguel`); }
  }
  if (comprovante === 'SIM') { score += 1; motivos.push('tem comprovante de renda'); }
  else if (comprovante === 'NAO') { score -= 1; motivos.push('sem comprovante de renda'); }
  else faltando.push('comprovante de renda');
  if (restricao === 'NAO') { score += 2; motivos.push('sem restrição informada'); }
  else if (restricao === 'SIM') { score -= 3; motivos.push('informou restrição no nome'); }
  else faltando.push('situação de restrição');
  if (['CAUCAO', 'FIADOR', 'SEGURO_FIANCA'].includes(garantia)) { score += 1; motivos.push(`garantia disponível: ${garantia}`); }
  else faltando.push('garantia de locação');
}

score = Math.max(0, Math.min(10, score));

let temperatura;
if (faltando.length >= 3) temperatura = 'PRECISA_DADOS';
else if (score >= minQuente) temperatura = 'LEAD_QUENTE';
else if (score >= minMedio) temperatura = 'LEAD_MEDIO';
else temperatura = 'LEAD_FRIO';

// Travas comerciais
if (!temImovel) temperatura = 'PRECISA_ESCOLHER_IMOVEL';
if (restricao === 'SIM' && score > minMedio) temperatura = 'LEAD_MEDIO';

const badge = temperatura === 'LEAD_QUENTE' ? '🔥 QUENTE' :
  temperatura === 'LEAD_MEDIO' ? '⚠️ MÉDIO' :
  temperatura === 'PRECISA_DADOS' ? '🟡 PRECISA DADOS' :
  temperatura === 'PRECISA_ESCOLHER_IMOVEL' ? '🏠 PRECISA ESCOLHER IMÓVEL' : '❄️ FRIO';

const prioridade = temperatura === 'LEAD_QUENTE' ? 'ALTA - chamar agora' :
  temperatura === 'LEAD_MEDIO' ? 'MÉDIA - nutrir e validar dados' :
  temperatura === 'PRECISA_DADOS' ? 'MÉDIA - coletar dados faltantes' :
  temperatura === 'PRECISA_ESCOLHER_IMOVEL' ? 'BAIXA/MÉDIA - ajudar a escolher imóvel' : 'BAIXA - manter relacionamento';

const resumoFinanceiro = a.resumo_financeiro || [
  renda ? `Renda: R$ ${renda}` : '',
  valorAluguel ? `Aluguel: R$ ${valorAluguel}` : '',
  valorImovel ? `Imóvel: R$ ${valorImovel}` : '',
  entrada ? `Entrada: R$ ${entrada}` : '',
  fgts !== 'NAO_INFORMADO' ? `FGTS: ${fgts}` : '',
  restricao !== 'NAO_INFORMADO' ? `Restrição: ${restricao}` : '',
  garantia !== 'NAO_INFORMADO' ? `Garantia: ${garantia}` : ''
].filter(Boolean).join(' | ');

let proximoPasso = a.proximo_passo || '';
if (!proximoPasso) {
  if (temperatura === 'LEAD_QUENTE') proximoPasso = 'Corretor deve chamar agora, confirmar dados e encaminhar para simulação/análise oficial.';
  else if (temperatura === 'LEAD_MEDIO') proximoPasso = 'Corretor deve validar dados faltantes e oferecer alternativas compatíveis.';
  else if (temperatura === 'PRECISA_DADOS') proximoPasso = `Coletar: ${faltando.join(', ')}.`;
  else if (temperatura === 'PRECISA_ESCOLHER_IMOVEL') proximoPasso = 'Ajudar o lead a escolher um imóvel específico antes da pré-análise.';
  else proximoPasso = 'Manter atendimento consultivo e enviar opções mais adequadas.';
}

return [{ json: {
  ...etapa,
  lgpd: 'aceito_pelo_cliente',
  tipo_negocio: tipo,
  valor_imovel: valorImovel,
  valor_aluguel: valorAluguel,
  renda_mensal: renda,
  entrada,
  fgts,
  restricao,
  comprovante_renda: comprovante,
  garantia_locacao: garantia,
  urgencia,
  score,
  temperatura,
  score_badge: badge,
  prioridade,
  motivos_score: motivos.join('; '),
  dados_faltantes: faltando.join(', '),
  resumo_financeiro: resumoFinanceiro,
