const config = $('Config Cliente').first().json;
const etapa = $('Normalizar Etapa do Lead').first().json;
const pergunta = String(etapa.pergunta_base_conhecimento || $('Edit Fields').first().json.message || '').trim();
const categoria = String(etapa.categoria_base_sugerida || '').toUpperCase();
const clienteId = String(config.cliente_id || '').trim();
const minScore = Number(config.confianca_minima_base || 6);

function norm(s) {
  return String(s || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function tokenize(s) {
  return norm(s).split(/[^a-z0-9]+/).filter(w => w.length >= 3);
}

let rows = [];
for (const item of $input.all()) {
  if (Array.isArray(item.json)) rows.push(...item.json);
  else if (Array.isArray(item.json.data)) rows.push(...item.json.data);
  else if (item.json && Object.keys(item.json).length) rows.push(item.json);
}

rows = rows.filter(r => {
  if (r.ativo === false) return false;
  if (!clienteId) return true;
  return !r.cliente_id || String(r.cliente_id) === clienteId;
});

const qTokens = tokenize(pergunta);
const scored = rows.map((r) => {
  const keywords = Array.isArray(r.palavras_chave) ? r.palavras_chave.join(' ') : (r.palavras_chave || '');
  const blob = `${r.categoria || ''} ${r.pergunta || ''} ${r.resposta || ''} ${keywords}`;
  const b = norm(blob);
  let score = Number(r.prioridade || 0);

  if (categoria && categoria !== 'VAZIO' && categoria !== 'OUTRO' && norm(r.categoria) === norm(categoria)) score += 8;
  for (const t of qTokens) if (b.includes(t)) score += 2;

  const common = {
    horario: ['horario','abre','fecha','atendimento','sabado','domingo'],
    localizacao: ['endereco','localizacao','onde fica','mapa','rua'],
    documento: ['documento','documentos','cpf','rg','comprovante'],
    financiamento: ['financiamento','financiar','caixa','banco','fgts'],
    visita: ['visita','agendar','conhecer','ver o imovel'],
    garantia: ['fiador','caucao','seguro fianca','garantia'],
    comissao: ['comissao','taxa','valor corretor']
  };
  const nq = norm(pergunta);
  for (const terms of Object.values(common)) {
    if (terms.some(t => nq.includes(norm(t))) && terms.some(t => b.includes(norm(t)))) score += 3;
  }
  return { ...r, score_match: score };
}).sort((a,b) => b.score_match - a.score_match);

const limite = Number(config.limite_base_conhecimento || 6);
const selecionadas = scored.filter(r => r.score_match >= minScore).slice(0, limite);
const melhorScore = scored[0]?.score_match || 0;

return [{
  json: {
    pergunta_base: pergunta,
    categoria_base_sugerida: categoria,
    total_base: rows.length,
    base_encontrada: selecionadas.length > 0,
    score_melhor_base: melhorScore,
    score_minimo_base: minScore,
    base_fallback: selecionadas.length === 0,
    respostas_base: selecionadas,
    melhor_resposta: selecionadas[0] || null,
    lead_id: $('Mesclar ID Lead Supabase').first().json.lead_id || ''
  }
}];

